package dev.tacticalcombat.client.ui;

import com.google.gson.*;
import dev.tacticalcombat.character.*;
import dev.tacticalcombat.uiapi.*;
import java.nio.file.*;
import java.util.*;
import static dev.tacticalcombat.client.ui.ManagementState.*;
import static dev.tacticalcombat.uiapi.UiApiService.Operation.*;

public final class CheckpointCPresentationTests {
    private static int count;
    private static void check(boolean value,String message){if(!value)throw new AssertionError(message);count++;}
    private static JsonObject ok(UiApiService api,CharacterRepository.Principal p,UiApiService.Operation op,JsonObject args){var r=api.handle(p,op,args);check(r.code().equals("OK"),op+": "+r.message());return r.data();}
    private static void reject(UiApiService api,CharacterRepository.Principal p,UiApiService.Operation op,JsonObject args){var r=api.handle(p,op,args);check(!r.code().equals("OK"),"Rejected "+op+": "+r.message());}
    private static JsonObject choices(Collection<String> skills,Collection<String> expertise,String mode){return SheetSections.JSON.toJsonTree(new CreationRules.Choices(List.copyOf(skills),List.copyOf(expertise),mode)).getAsJsonObject();}
    private static final class FocusHost extends RpgScreen {
        FocusHost(){super("Real parent focus sequence",null);}
        void attach(CharacterCanvas canvas){addDrawableChild(canvas);}
        void replace(CharacterCanvas old,CharacterCanvas next){remove(old);addDrawableChild(next);next.focus("alignment");setFocused(next);}
    }
    public static void run()throws Exception {
        var host=new FocusHost();var canvas=new CharacterCanvas(new UiLayout.Rect(0,0,240,180));host.attach(canvas);var value=new String[]{"True Neutral"};var dropdown=canvas.control("alignment",new AlignmentDropdown(5,40,120,()->value[0],v->value[0]=v,()->new UiLayout.Rect(0,0,240,180)));
        for(int i=0;i<8;i++){check(host.mouseClicked(10,44,0)&&dropdown.isOpen(),"Minecraft parent event opens/reopens popup without redundant blur");check(host.mouseClicked(10,60,0)&&!dropdown.isOpen(),"Minecraft parent selects without click-through");}
        check(host.getFocused()==canvas&&canvas.focusedKey().equals("alignment"),"Parent and child focus remain stable after selection");check(host.mouseClicked(10,44,0)&&dropdown.keyPressed(org.lwjgl.glfw.GLFW.GLFW_KEY_DOWN,0,0)&&dropdown.keyPressed(org.lwjgl.glfw.GLFW.GLFW_KEY_ENTER,0,0)&&!dropdown.isOpen(),"Keyboard navigation confirms selection after mouse reopen");
        var rebuilding=new FocusHost();CharacterCanvas old=new CharacterCanvas(new UiLayout.Rect(0,0,240,180)),next=new CharacterCanvas(new UiLayout.Rect(0,0,240,180));next.control("alignment",new AlignmentDropdown(5,40,120,()->"True Neutral",v->{},()->new UiLayout.Rect(0,0,240,180)));old.control("alignment",new AlignmentDropdown(5,40,120,()->"True Neutral",v->rebuilding.replace(old,next),()->new UiLayout.Rect(0,0,240,180)));rebuilding.attach(old);check(rebuilding.mouseClicked(10,44,0)&&rebuilding.mouseClicked(10,60,0)&&rebuilding.getFocused()==next,"Preview rebuild retains focus in live canvas, not removed canvas");
        for(int[] size:List.of(new int[]{320,240},new int[]{480,270},new int[]{640,360},new int[]{960,540},new int[]{1280,720})){var frame=UiLayout.frame(size[0],size[1],980);var nav=WizardChildLayout.rail(frame);var content=WizardChildLayout.content(frame);check(nav.fits(size[0],size[1])&&content.fits(size[0],size[1])&&!nav.overlaps(content),"Guided child navigation and content fit without overlap");var body=DashboardLayout.body(frame);var layout=CharacterSheetUi.layout(body.width());if(size[0]>=640&&size[1]>=360)check(layout.equipmentTop()<=body.height(),"Essential compact sheet fits before equipment at practical logical size");else check(layout.equipmentTop()>0,"Small logical viewport retains safe scrolling");}
        var errors=new JsonArray();errors.add(args("section","class","code","CLASS_REQUIRED","message","Choose a class"));var currentValidation=DraftReplies.validationFromSnapshot(args("errors",errors));check(CreatorFlow.errorStep(text(array(currentValidation,"errors").get(0).getAsJsonObject(),"section"))==CreatorFlow.Step.CLASS,"Missing class correction routes directly to Class");check(array(DraftReplies.validationFromSnapshot(args("errors",new JsonArray())),"errors").isEmpty(),"Fresh successful snapshot clears prior blocking review issues");check(DraftReplies.validationFromSnapshot(new JsonObject())==null,"Missing validation metadata triggers an authoritative refresh, not invented success");
        var dir=Files.createTempDirectory("checkpoint-c-presentation");var repo=new CharacterRepository(dir.resolve("campaigns.json"));var library=new LibraryRepository(dir.resolve("library.json"));var api=new UiApiService(repo,library,(op,a)->{throw new IllegalArgumentException("No runtime adapter");});var owner=new CharacterRepository.Principal(UUID.randomUUID(),false);
        var draft=ok(api,owner,LIBRARY_CREATE,args("profile","srd_5_1","mode","MANUAL","sheet",null));var source=new DashboardSource(true,text(draft,"id"));
        var inventory=SheetSections.read(draft.getAsJsonObject("sheet"),"inventory");var money=new CurrencyDraft(inventory);for(int i=0;i<5;i++)money.values.put(CurrencyDraft.KEYS.get(i),Integer.toString((i+1)*11));var sent=Map.copyOf(money.values);draft=ok(api,owner,LIBRARY_UPDATE,source.sectionArgs(draft,"inventory",money.data(inventory)));inventory=SheetSections.read(draft.getAsJsonObject("sheet"),"inventory");money.values.put("gold","99");money.accept(inventory,sent);check(money.dirty()&&money.values.get("gold").equals("99"),"Currency acknowledgement preserves typing newer than dispatch");var external=inventory.deepCopy();external.addProperty("platinum",777);money.accept(external,null);check(money.conflict(),"Concurrent server currency requires review");money.reviewed();check(!money.conflict(),"Review anchors actual currency baseline");for(String key:CurrencyDraft.KEYS)check(inventory.get(key).getAsInt()==(CurrencyDraft.KEYS.indexOf(key)+1)*11,"All five inline currencies persist");var badMoney=inventory.deepCopy();badMoney.addProperty("gold",-1);reject(api,owner,LIBRARY_UPDATE,source.sectionArgs(draft,"inventory",badMoney));badMoney=inventory.deepCopy();badMoney.addProperty("gold",1.5);reject(api,owner,LIBRARY_UPDATE,source.sectionArgs(draft,"inventory",badMoney));
        var catalog=SheetSections.JSON.toJsonTree(new SheetSections.Item("custom:catalog1","srd:weapon:DAGGER","dagger",1,false,"",List.of("FINESSE"),"Catalog entry","")).getAsJsonObject();var first=InventoryModel.catalogAddition(inventory,catalog,false);var secondBlueprint=catalog.deepCopy();secondBlueprint.addProperty("id","custom:catalog2");var stack=InventoryModel.catalogAddition(first,secondBlueprint,false);check(array(stack,"items").size()==1&&InventoryModel.find(stack,"custom:catalog1").get("quantity").getAsInt()==2,"Catalog addition deterministically stacks matching records and retains identifier");var separate=InventoryModel.catalogAddition(stack,secondBlueprint,true);check(array(separate,"items").size()==2,"Explicit separate-instance catalog action preserves distinct records");check(array(InventoryModel.quantity(separate,"custom:catalog1",1),"items").size()==2,"Quantity plus never creates an entry");var combatBefore=dev.tacticalcombat.rules.srd.SrdAuthoring.data(draft.getAsJsonObject("sheet"));long stale=revision(draft);draft=ok(api,owner,LIBRARY_UPDATE,source.sectionArgs(draft,"inventory",separate));reject(api,owner,LIBRARY_UPDATE,args("character",source.character(),"revision",stale,"section","inventory","data",separate));check(combatBefore.equals(dev.tacticalcombat.rules.srd.SrdAuthoring.data(draft.getAsJsonObject("sheet"))),"Inline currency/catalog/equipment do not modify combat fields");
        var hp=dev.tacticalcombat.rules.srd.SrdAuthoring.data(draft.getAsJsonObject("sheet"));var hpMax=hp.get("hp_max").getAsInt();hp.addProperty("hp",hpMax+1);reject(api,owner,LIBRARY_UPDATE,source.sectionArgs(draft,"combat",hp));hp.addProperty("hp",-1);reject(api,owner,LIBRARY_UPDATE,source.sectionArgs(draft,"combat",hp));hp.addProperty("hp",hpMax);hp.addProperty("temporary_hp",5);draft=ok(api,owner,LIBRARY_UPDATE,source.sectionArgs(draft,"combat",hp));check(dev.tacticalcombat.rules.srd.SrdAuthoring.data(draft.getAsJsonObject("sheet")).get("hp").getAsInt()==hpMax,"Temporary HP does not overflow normal maximum");draft=ok(api,owner,LIBRARY_FINALIZE,args("character",source.character(),"revision",revision(draft)));
        var restarted=new LibraryRepository(dir.resolve("library.json")).get(owner,UUID.fromString(source.character()));var persisted=JsonParser.parseString(restarted.sheet()).getAsJsonObject();check(SheetSections.read(persisted,"inventory").get("platinum").getAsInt()==55&&array(SheetSections.read(persisted,"inventory"),"items").size()==2,"Currency/item instances survive world repository restart");
        System.out.println("Checkpoint C presentation checks passed: "+count);
    }
}
